.welcome-title { align-self: start; padding-top: 1px; font: italic 500 clamp(1.05rem, calc((var(--hero-unit) * .8) + 10.4px), 1.15rem)/1.4 'Cormorant Garamond', Georgia, serif; white-space: nowrap; transition: transform 220ms cubic-bezier(.22,1,.36,1); }
.welcome-caption { position: relative; display: flex; align-items: center; justify-content: space-between; gap: 8px; margin: -22px 0 0 calc(var(--welcome-icon-size) + var(--welcome-icon-gap)); }
.welcome-byline { color: var(--muted, #777); font-size: .59rem; white-space: nowrap; font-variant-numeric: tabular-nums; }
.welcome-languages { display: flex; gap: 4px; }
.welcome-languages button { min-width: 30px; min-height: 32px; padding: 0 3px; border: 0; background: transparent; color: var(--muted, #777); opacity: .65; font-family: inherit; font-size: .62rem; line-height: 1; cursor: pointer; transition: opacity 160ms ease; }
.welcome-languages button[aria-pressed='true'] { color: inherit; opacity: 1; }
.welcome-languages button[aria-pressed='true']::after { content: ''; display: block; width: 3px; height: 3px; margin: 4px auto -7px; border-radius: 50%; background: currentColor; }
.welcome-audio button:focus-visible { outline: 1px solid currentColor; outline-offset: 3px; }
.welcome-play:focus-visible * { transition: none; }
