@media (hover: hover) and (pointer: fine) {
  .welcome-play:hover .welcome-orbit-line { transform: rotate(12deg); opacity: .7; }
  .welcome-play:hover .welcome-title { transform: translateX(2px); }
  .welcome-languages button:hover { opacity: 1; }
}
@media (prefers-reduced-motion: reduce) {
  .welcome-audio * { transition: none !important; }
